CREATE TABLE users(user_id TEXT PRIMARY KEY,username TEXT,nickname TEXT,avatar_url TEXT,is_bot BOOLEAN);
CREATE TABLE threads(thread_id TEXT PRIMARY KEY,category_id TEXT,name TEXT,exported_at TEXT,guild_id TEXT,last_active_at TEXT);
CREATE TABLE thread_scan_state(thread_id TEXT PRIMARY KEY,name TEXT,last_active_at TEXT,scanned_at TEXT,guild_id TEXT);
CREATE TABLE messages(message_id TEXT PRIMARY KEY,thread_id TEXT,author_id TEXT,content TEXT,timestamp DATETIME,reply_to_msg_id TEXT);
CREATE TABLE reactions(id INTEGER PRIMARY KEY AUTOINCREMENT,message_id TEXT,user_id TEXT,emoji_name TEXT,emoji_url TEXT);
CREATE TABLE attachments(id INTEGER PRIMARY KEY AUTOINCREMENT,message_id TEXT,url TEXT,filename TEXT,size_bytes INTEGER);
CREATE TABLE mentions(id INTEGER PRIMARY KEY AUTOINCREMENT,message_id TEXT,mentioned_user_id TEXT,author_id TEXT);
CREATE TABLE user_stats(user_id TEXT PRIMARY KEY,msg_count INTEGER DEFAULT 0,reaction_received_count INTEGER DEFAULT 0,interaction_score INTEGER DEFAULT 0,first_msg_at DATETIME,last_msg_at DATETIME);
CREATE TABLE user_merges(target_id TEXT PRIMARY KEY,parent_id TEXT,created_at DATETIME);
CREATE TABLE claim_requests_v2(id INTEGER PRIMARY KEY AUTOINCREMENT,requester_id TEXT,target_id TEXT,target_name TEXT,status INTEGER DEFAULT 0,created_at DATETIME,UNIQUE(requester_id,target_id));
CREATE TABLE web_visitors(user_id TEXT PRIMARY KEY,username TEXT,nickname TEXT,avatar_url TEXT,last_visit DATETIME);
CREATE TABLE profile_views(id INTEGER PRIMARY KEY AUTOINCREMENT,target_user_id TEXT,viewer_user_id TEXT,viewer_name TEXT,viewer_avatar TEXT,timestamp DATETIME,UNIQUE(target_user_id,viewer_user_id));
CREATE INDEX idx_msg_author ON messages(author_id);
CREATE INDEX idx_msg_author_message ON messages(author_id,message_id);
CREATE INDEX idx_msg_author_thread ON messages(author_id,thread_id);
CREATE INDEX idx_msg_timestamp ON messages(timestamp);
CREATE INDEX idx_msg_thread ON messages(thread_id);
CREATE INDEX idx_msg_author_timestamp ON messages(author_id,timestamp);
CREATE INDEX idx_msg_thread_timestamp ON messages(thread_id,timestamp);
CREATE INDEX idx_react_user ON reactions(user_id);
CREATE INDEX idx_react_user_message ON reactions(user_id,message_id);
CREATE INDEX idx_react_msg ON reactions(message_id);
CREATE INDEX idx_react_msg_user ON reactions(message_id,user_id);
CREATE INDEX idx_mentions_user ON mentions(mentioned_user_id);
CREATE INDEX idx_mentions_author ON mentions(author_id);
CREATE INDEX idx_attach_msg ON attachments(message_id);
CREATE INDEX idx_stats_count ON user_stats(msg_count);
CREATE INDEX idx_msg_hour ON messages(strftime('%H', timestamp));
CREATE INDEX idx_msg_day  ON messages(substr(timestamp, 1, 10));
CREATE INDEX idx_react_msg_id ON reactions(message_id, id);
